'use strict';const {test}=require('node:test');const assert=require('node:assert/strict');const fs=require('node:fs');const {createUiState}=require('./radar-ui');
const car={id:'v',name:'Voiture',fuel:'Gazole',fillPercent:80,tankCapacity:50,consumption:6,illustration:'berline'};const garage={schemaVersion:1,revision:1,defaultVehicleId:'v',vehicles:[car]};const stations=[{id:'1',name:'A',price:1.6},{id:'2',name:'B',price:1.7},{id:'3',name:'C',price:1.8}];const route={id:'1',totalCost:66.1,distanceRoundTripKm:10,durationOutboundMinutes:7.2};const ranking={top:[route],calculated:[route],uncalculated:['2','3'],unavailable:[],certified:false};
const setup=(hooks={})=>createUiState({garage,stations,ranking,...hooks});
test('jauge 80 par défaut',()=>assert.equal(setup().snapshot().fillPercent,80));
test('top affiche coût distance temps',()=>{const s=setup().snapshot().cards[0];assert.equal(s.totalCost,66.1);assert.equal(s.distanceRoundTripKm,10);assert.equal(s.durationOutboundMinutes,8)});
test('voir plus masque puis affiche',()=>{const x=setup();assert.equal(x.snapshot().hiddenCount,2);assert.equal(x.toggleMore().more.length,2);assert.equal(x.toggleMore().more.length,0)});
test('station sans itinéraire affiche null',()=>{const x=setup();assert.equal(x.toggleMore().more[0].totalCost,null)});
test('calcul individuel déclenche callback',()=>{let id;const x=setup({onCalculate:v=>id=v});x.toggleMore();x.calculate('2');assert.equal(id,'2')});
test('ne recalcule pas déjà calculée',()=>assert.throws(()=>setup().calculate('1')));
test('sélection véhicule invalide refusée',()=>assert.throws(()=>setup().selectVehicle('inconnu')));
test('jauge invalide refusée',()=>assert.throws(()=>setup().setFillPercent(0)));
test('jauge émet un callback',()=>{let val;const x=setup({onFillChange:(_,p)=>val=p});x.setFillPercent(45);assert.equal(val,45)});
test('changement de véhicule réinitialise la jauge',()=>{const x=setup();x.setFillPercent(30);x.selectVehicle('v');assert.equal(x.snapshot().fillPercent,80)});
test('pas de véhicule demande un ajout',()=>{const x=createUiState({garage:{...garage,vehicles:[],defaultVehicleId:null}});assert.equal(x.snapshot().status,'needs_vehicle')});
test('pas de classement affiche chargement',()=>{const x=createUiState({garage,ranking:null});assert.equal(x.snapshot().status,'loading')});
test('classement non certifié explicite',()=>assert.equal(setup().snapshot().status,'unverified'));
test('classement certifié explicite',()=>assert.equal(createUiState({garage,stations,ranking:{...ranking,certified:true}}).snapshot().status,'verified'));
test('mise à jour de données conserve Voir plus',()=>{const x=setup();x.toggleMore();x.setData({ranking});assert.equal(x.snapshot().showMore,true)});
test('identifiant de station conservé comme chaîne',()=>assert.equal(setup().snapshot().cards[0].id,'1'));
test('HTML accessible possède ses contrôles',()=>{const s=fs.readFileSync(__dirname+'/radar-interface.html','utf8');for(const id of ['vehicle','fill','moreBtn','status','top','more'])assert.match(s,new RegExp('id="'+id+'"'))});
test('HTML n’envoie aucune requête automatiquement',()=>{const s=fs.readFileSync(__dirname+'/radar-interface.html','utf8');assert.doesNotMatch(s,/fetch\s*\(/)});
